package practice_1;public class Num13 {    public static void main(String[] args) {        int [] numbers = {0, 5, -4, 7, 6};        int sum = 0;        for (int i = 0; i < numbers.length; i++) {            sum += numbers[i];        }        double average = (double) sum / numbers.length;        System.out.println("Сумма элементов массива: " + sum);        System.out.println("Среднее арифметическое его элементов: " + average);    }}